import{_ as i,o as p,c as t,ae as a}from"./chunks/framework.BrEqZt6s.js";const _=JSON.parse('{"title":"<26.03.14(토)>","description":"","frontmatter":{},"headers":[],"relativePath":"clubActivities/MIRO/03-14.md","filePath":"clubActivities/MIRO/03-14.md"}'),u={name:"clubActivities/MIRO/03-14.md"};function e(r,l,S,o,s,c){return p(),t("div",null,[...l[0]||(l[0]=[a('<h1 id="_26-03-14-토" tabindex="-1">&lt;26.03.14(토)&gt; <a class="header-anchor" href="#_26-03-14-토" aria-label="Permalink to &quot;&lt;26.03.14(토)&gt;&quot;">​</a></h1><p>김승년</p><ul><li>삼성전자: HBM, AI시대 곡괭이 반도체, 영상으로 갈수록 사용량 급증(만극 등등)</li><li>롯데케미칼: 석유화학, 적자 원인 중국 저가공세, 러시아와 이란에서 원료 떼와서 싸게 만듦, 러시아 원유 제재 일시적 해제, PBR 0.2</li></ul><p>정선경</p><ul><li>삼성SDI: 앞으로 휴머노이드 로봇 전고체 배터리 개발</li><li>휴메딕스: 티타임에서 리투오 얘기 듣고 리쥬란만큼의 가능성을 보고 매수</li></ul><p>노문재</p><ul><li>현대마린엔진: 조선 사이클 유효하다고 봄, 이란-미국 전쟁으로 괜찮게 봄</li><li>한화엔진:</li><li>한화생명: 자사주 소각, PBR 낮음,</li><li>NAVER: 두나무 합병이슈</li></ul><p>윤창숙</p><ul><li>효성중공업: AI데이터센터, 전기차, 전력망 교체로 인한 전력기기 수요 폭증, 북미 1티어이자 최대 점유율, 28년까지 수주잔고 확보</li><li>LS일렉트릭, HD현대일렉트릭 같은 아이디어</li></ul><p>박은기</p><ul><li>메리츠금융지주: 회장이 PER 10 공언 135000원</li><li>한전KPS: 배당수익률 3.5%</li><li>기아: 배당수익률 3~4%, 배당을 계속 늘려갈 거라고 봄</li><li>엔터주:</li></ul><p>최명식</p><ul><li>한미반도체: 앞으로도 HBM 잘될 거 같아서</li><li>메지온: 3상 임상 중인데 중간 데이터가 너무 잘나옴, PRV 신청으로 결정되면 LO 가능성</li></ul><p>김시완</p><ul><li>삼성전자: HBM 다음으로 HBF를 보고 있음</li><li>에임드바이오: 삼성자산운용이 1호로 국내에 투자한게 에임드바이오, 에임드바이오의 ADC바이오 기술이 …..</li></ul><p>추혜경</p><ul><li>미래에셋증권: 스페이스X 지분 보유로 IPO시 수혜, 코인원 인수, 내수진작과 증시 부양의 수혜</li><li>RFHIC: 통신장비, GaN, 전쟁이슈로 테마묻을 수 있음, 무기 회사가 아니라서 테마 강도가 낮음</li></ul><p>유정윤</p><ul><li>삼성SDI: 주변에서 주워듣고 매수, 전고체배터리</li><li>LG화학:</li><li>롯데에너지머티리얼즈: 2차전지 독보적인 기술 보유</li></ul><p>박진애</p><ul><li>현대로템: 지상무기(탱크 등), 이번 전쟁은 드론이나 미사일로 하고 있어서 수혜정도가 낮음</li><li>두산에너빌리티:</li><li>킵스파마: 남편 분이 유튜브 보고 추천, 영장류에 처음 실험된다고 함, 일단 남편분의 강력한 의지로 보유</li></ul><p>박지환</p><ul><li>한국카본: LNG운반선에 들어가는 보냉재 회사, 세컨드배리어(SB) 트리플X 한국카본만 제조 가능, 저가수주 물량 해소, 고가수주,</li><li>에이디테크놀로지: 추론시장에서 AI서비스가 다양해질거고 ASIC가 잘 될텐데 반도체 설계를 도와주는 디자인 하우스 회사들이 수혜를 볼 것, 삼성전자 파운드리 하청</li></ul><p>이경득</p><ul><li>QQQ+VOO: 상장된 이후로 연평균 수익률 10%이므로 생각없이 투자하기 좋음</li></ul><p>이승현</p><ul><li>이더리움</li><li>서클(CRCL): USDC, 스테이블코인, 전자결제관련</li></ul><p>이세진</p><ul><li>비트코인레버리지</li><li>코인베이스: 코인거래소</li><li>한강프로젝트</li></ul><p>장효원</p><ul><li>LG화학: 전쟁으로 인한 유가상승으로 중국공장 가동률 하락예상, 재가동하는데에 시간이 걸림, 단기적으로 쇼티지 예상,</li><li>트랜스오션, 시드릴: 해양시추, 드릴쉽 쇼티지(공급부족)</li></ul><p>하종호</p><ul><li>금호석유화학: 고유가</li><li>옵티코어: 광트랜시버, 400G에서 800G로 가는 데에 수혜를 보는 종목이라고 생각함</li></ul><p>김은지</p><ul><li>티웨이항공</li><li>메가스터디</li><li>QQQ+SPY: 미중양강구도가 무너지지 않는 이상 수익을 볼 거라 예상</li><li>트루스소셜: 트럼프ETF</li><li>TSES, TSIC, TSNF, TSRS, TSSD</li></ul><p>여동호</p><ul><li>엘앤에프: ESS 필요성 대두, ESS에서 비중 제일 높은게 배터리, 그안에서도 양극재, LFP 중국 제외 엘앤에프가 비중 제일 높음, 양산 시점도 가장 빠름, 하이니켈 LG화학 밀어냄, 국내3사 셀에 공급</li><li>LS머트리얼즈: 대형 슈퍼커패시터(울트라커패시터), 무정전 보조장치(UPS) 등에 사용, 고출력 장수명 급속 충방전, 반도체 노광공정에 주파수 관리용으로도 필요함</li><li>SKC: 신사업으로 유리기판 시장 진출, 경쟁사보다 빠를 듯, 논임베딩 유리기판(덜 완제품) 소규모 상업적 출하를 목표로 수율 끌어올리기 용이하다고 봄, 27년 양산 목표, 미국 엔비디아 AMD 등등 퀄테스트 진행중, 베라루빈부터는 유리기판 사용하지 않을까, 두께도 줄이고 전력소비도 줄일 수 있음, 대면적 패키징, 통신속도도 30% 향상, 유증 1조 중 유리기판 자회사 5900억, 어플라이드머티리얼즈에서 지분투자 및 협력해서 유리기판 양산에 힘쓰고 있음, 자회사로 테스트 소켓하는 ISC</li></ul><hr><h2 id="비나텍" tabindex="-1">비나텍? <a class="header-anchor" href="#비나텍" aria-label="Permalink to &quot;비나텍?&quot;">​</a></h2><p>배경지식 블룸에너지: SOFC(고체산화물연료전지)제작 기업 1위</p><p>SOFC 연료 -&gt; 전기발생 고효율 도시가스, 수소 등등 유틸이 좋음 시동거는데 오래걸리고, 출력 변경이 힘듦</p><p>블룸에너지 : 정전시 반응을 위한 고출력 컴페시터 필요 -&gt; 비나텍이 공유</p><p>슈퍼컴페시터가 SOFC의 느린 변동성을 보완</p><ol><li>SOFC에 컴페시터 필요</li><li>AI부하변동에 도움 (컴페시터를 통해)</li></ol><p>비나텍이 셀 생성 -&gt; 대만업체에서 컴페시터 렉(컴페시터 모음)으로 조립-&gt; 블룸에너지가 설치</p><p>블룸에너지의 비나텍 증설 요청 대만업체가 물량처리 X -&gt; 블룸에너지: 비나텍 너희도 만들어 =&gt; 중간유통, 조립비 까지 흡수 +(시스템(렉)까지 만든다면?)</p><p>엔비디아에 샘플 납품 데이터 전력효율을 위해 800V 직류..</p><h3 id="문제" tabindex="-1">문제. <a class="header-anchor" href="#문제" aria-label="Permalink to &quot;문제.&quot;">​</a></h3><p>블룸에너지 의존도가 높다.. LNG(액화 천연가스)수출막히면서 -&gt; SOFC 돌리기 위한 천연가스 문제 미국 본토는 천연가스 나와서 상관 X 그 외 지역에 문제 가능..</p>',49)])])}const d=i(u,[["render",e]]);export{_ as __pageData,d as default};
